def get_max_sum(n: int) -> int:
    """Return f(n) where f(n) = max(f(n//2) + f(n//3) + f(n//4) + f(n//5), n)."""
    if n <= 0:
        return 0
    split = get_max_sum(n // 2) + get_max_sum(n // 3) + get_max_sum(n // 4) + get_max_sum(n // 5)
    return max(split, n)

