def amicable_numbers_sum(n: int) -> int:
    """Return the sum of all amicable numbers from 1 to n (inclusive).

    A number a is amicable if d(a) = sum of proper divisors of a equals b,
    where d(b) = a and a != b.
    """
    if n < 2:
        return 0

    # Sieve the sum of proper divisors for every value up to n.
    divisor_sum = [0] * (n + 1)
    for i in range(1, n // 2 + 1):
        for multiple in range(2 * i, n + 1, i):
            divisor_sum[multiple] += i

    total = 0
    for a in range(2, n + 1):
        b = divisor_sum[a]
        if b != a and b <= n and divisor_sum[b] == a:
            total += a
    return total

