def _proper_divisor_sum(x: int) -> int:
    """Sum of proper divisors of x (x >= 1), via trial division up to sqrt(x)."""
    if x < 2:
        return 0
    total = 1
    i = 2
    while i * i <= x:
        if x % i == 0:
            total += i
            j = x // i
            if j != i:
                total += j
        i += 1
    return total


