def amicable_numbers_sum(n: int) -> int:
    """Return the sum of all amicable numbers x with 1 <= x <= n.

    x is amicable if d(d(x)) == x and d(x) != x, where d(x) is the sum of
    proper divisors of x. The partner d(x) may exceed n; it is still valid.
    """
    if n < 2:
        return 0

    # Sieve proper-divisor sums for 0..n.
    divisor_sum = [0] * (n + 1)
    for i in range(1, n // 2 + 1):
        for multiple in range(2 * i, n + 1, i):
            divisor_sum[multiple] += i

    total = 0
    for a in range(2, n + 1):
        b = divisor_sum[a]
        if b == a:
            continue
        d_b = divisor_sum[b] if b <= n else _proper_divisor_sum(b)
        if d_b == a:
            total += a
    return total

def _proper_divisor_sum(x: int) -> int:
    """Sum of proper divisors of x, via trial division up to sqrt(x)."""
    if x < 2:
        return 0
    total = 1
    i = 2
    while i * i <= x:
        if x % i == 0:
            total += i
            j = x // i
            if j != i:
                total += j
        i += 1
    return total


def _sieve_divisor_sums(limit: int) -> list:
    """Return list s where s[k] is the sum of proper divisors of k, for 0 <= k <= limit."""
    s = [0] * (limit + 1)
    for i in range(1, limit // 2 + 1):
        for multiple in range(2 * i, limit + 1, i):
            s[multiple] += i
    return s


