    """Return the sum of all amicable numbers x with 1 <= x <= n.

    x is amicable if d(d(x)) == x and d(x) != x, where d(x) is the sum of
    proper divisors of x. The partner d(x) may exceed n; it is still valid.
    """
    if n < 2:
        return 0

    # Sieve up to a bound that covers the partners of most x <= n;
    # anything larger falls back to trial division.
    limit = 2 * n
    s = _sieve_divisor_sums(limit)

    total = 0
    for a in range(2, n + 1):
        b = s[a]
        if b == a:
            continue
        d_b = s[b] if b <= limit else _proper_divisor_sum(b)
        if d_b == a:
            total += a
    return total

