def cal_sum(n):
    """Return the sum of the first n+1 Perrin numbers, P(0) through P(n).

    Perrin sequence: P(0)=3, P(1)=0, P(2)=2, P(k)=P(k-2)+P(k-3).
    """
    if n < 0:
        return 0
    p = [3, 0, 2]
    for k in range(3, n + 1):
        p.append(p[k - 2] + p[k - 3])
    return sum(p[:n + 1])

