def sum_range_list(nums, start, end):
    """Return the sum of elements of nums from index start to end inclusive.

    Negative indices count from the end of the list (Python-style).
    Out-of-range bounds are clipped to the list; an empty range sums to 0.
    """
    n = len(nums)
    if start < 0:
        start += n
    if end < 0:
        end += n
    start = max(start, 0)
    end = min(end, n - 1)
    if start > end:
        return 0
    return sum(nums[start:end + 1])

