def divisible_by_digits(startnum, endnum):
    """Return numbers in [startnum, endnum] divisible by every digit they contain.

    A number containing a 0 digit is excluded, since n is never divisible by 0.
    """
    result = []
    for n in range(startnum, endnum + 1):
        digits = [int(d) for d in str(n)]
        if all(d != 0 and n % d == 0 for d in digits):
            result.append(n)
    return result


