def max_sum(arr):
    """Return the maximum sum of a bitonic subsequence of arr.

    A bitonic subsequence is strictly increasing then strictly decreasing
    (either part may be empty). Runs in O(n^2) time, O(n) space.
    """
    n = len(arr)
    if n == 0:
        return 0

    # inc[i]: max sum of an increasing subsequence ending at index i
    inc = list(arr)
    for i in range(n):
        for j in range(i):
            if arr[j] < arr[i] and inc[j] + arr[i] > inc[i]:
                inc[i] = inc[j] + arr[i]

    # dec[i]: max sum of a decreasing subsequence starting at index i
    dec = list(arr)
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if arr[j] < arr[i] and dec[j] + arr[i] > dec[i]:
                dec[i] = dec[j] + arr[i]

    # The peak arr[i] is counted in both inc and dec, so subtract it once.
    return max(inc[i] + dec[i] - arr[i] for i in range(n))

