def _count_odds_upto(n):
    """Number of odd natural numbers in [1, n]."""
    if n < 1:
        return 0
    return (n + 1) // 2


def sum_in_range(l, r):
    """Return the sum of all odd natural numbers in the inclusive range [l, r].

    The first k odd numbers sum to k**2, so the sum of odds in [l, r] is
    k(r)**2 - k(l-1)**2, where k(n) is the count of odd naturals <= n.
    """
    if r < l:
        return 0
    return _count_odds_upto(r) ** 2 - _count_odds_upto(l - 1) ** 2

