    For n < 5, the factorial is small, so compute it directly.
    """
    if n < 0:
        raise ValueError("factorial is not defined for negative numbers")
    if n >= 5:
        return 0
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result % 10

