def lps(s: str) -> int:
    """Return the length of the longest palindromic subsequence of s."""
    n = len(s)
    if n == 0:
        return 0
    # dp[i][j] = LPS length within s[i..j]; fill by increasing span.
    # Keep only the row for i+1 and the current row i to save memory.
    prev = [0] * n  # row i+1
    for i in range(n - 1, -1, -1):
        cur = [0] * n
        cur[i] = 1
        for j in range(i + 1, n):
            if s[i] == s[j]:
                cur[j] = prev[j - 1] + 2 if j - 1 >= i + 1 else 2
            else:
                cur[j] = max(prev[j], cur[j - 1])
        prev = cur
    return prev[n - 1]

