def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    result = []
    for ch in string:
        if ch.islower():
            up = ch.upper()
            # Only flip when the result stays a single character, so the
            # output length always matches the input (e.g. 'ß' stays 'ß').
            result.append(up if len(up) == 1 else ch)
        elif ch.isupper():
            low = ch.lower()
            result.append(low if len(low) == 1 else ch)
        else:
            result.append(ch)
    return ''.join(result)

