def maxAverageOfPath(matrix):
    """
    Return the maximum average cell cost over all right/down paths from the
    top-left to the bottom-right cell of a square matrix.

    Every such path visits exactly 2N-1 cells, so maximizing the average is
    the same as maximizing the total cost. A DP over the grid finds the
    maximum-sum path in O(N^2).
    """
    n = len(matrix)
    if n == 0:
        return 0.0

    best = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            cell = matrix[i][j]
            if i == 0 and j == 0:
                best[i][j] = cell
            elif i == 0:
                best[i][j] = best[i][j - 1] + cell
            elif j == 0:
                best[i][j] = best[i - 1][j] + cell
            else:
                best[i][j] = max(best[i - 1][j], best[i][j - 1]) + cell

    path_len = 2 * n - 1
    return best[n - 1][n - 1] / path_len

