from functools import reduce


def common_in_nested_lists(nested_lists):
    """Return the elements common to every list in nested_lists.

    Hashable elements are intersected as sets, so output order follows set
    iteration order. Unhashable elements (e.g. lists) fall back to an
    order-preserving filter over the first list.
    """
    if not nested_lists:
        return []
    try:
        return list(reduce(lambda a, b: a & b, (set(x) for x in nested_lists)))
    except TypeError:
        first, others = nested_lists[0], nested_lists[1:]
        result = []
        for item in first:
            if item in result:
                continue
            if all(item in other for other in others):
                result.append(item)
        return result

