def find_min_diff(arr, n=None):
    """Return the minimum absolute difference between any two elements of arr.

    Only the first n elements are considered (default: all of them). After
    sorting, the closest pair must be adjacent, so one pass over the sorted
    values is enough: O(n log n) time.
    """
    if n is None:
        n = len(arr)
    values = sorted(arr[:n])
    if len(values) < 2:
        return float("inf")
    return min(b - a for a, b in zip(values, values[1:]))

