def find_solution(a, b, n):
    """Return (x, y) with x, y >= 0 and a*x + b*y == n, or None if none exists.

    The solution returned has the smallest possible x. Assumes a, b, n are
    non-negative integers.
    """
    if n < 0 or a < 0 or b < 0:
        return None

    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        return (0, n // b) if n % b == 0 else None
    if b == 0:
        return (n // a, 0) if n % a == 0 else None

    # Residues of a*x mod b repeat with period b / gcd(a, b), so any
    # smallest solution has x < b. Also x cannot exceed n // a.
    for x in range(min(b, n // a + 1)):
        rest = n - a * x
        if rest % b == 0:
            return (x, rest // b)
    return None

