def replace_spaces(text):
    """Swap whitespace and underscores: spaces become '_' and '_' becomes spaces.

    Other whitespace characters (tabs, newlines) are converted to '_' as well,
    and underscores are converted to spaces.
    """
    result = []
    for ch in text:
        if ch == '_':
            result.append(' ')
        elif ch.isspace():
            result.append('_')
        else:
            result.append(ch)
    return ''.join(result)


