def toggle_string(s: str) -> str:
    """Return s with the case of every character toggled.

    Each character is toggled on its own, and the result keeps the same
    length as the input. Characters whose case change would expand to more
    than one character (e.g. 'ß' -> 'SS') are left unchanged.
    """
    out = []
    for c in s:
        if c.isupper():
            t = c.lower()
        elif c.islower():
            t = c.upper()
        else:
            t = c
        out.append(t if len(t) == 1 else c)
    return "".join(out)


