def valid_date(date):
    """Validate a date string in the format mm-dd-yyyy.

    Returns True if the date is valid, otherwise False.
    Rules:
      1. The string is not empty.
      2. Days: 1-31 for months 1,3,5,7,8,10,12; 1-30 for months 4,6,9,11;
         1-29 for month 2.
      3. Months: 1-12.
      4. The string is three '-'-separated numeric parts: month, day, year.
    """
    if not date or not isinstance(date, str):
        return False

    parts = date.split('-')
    if len(parts) != 3:
        return False

    month_s, day_s, year_s = parts
    # isdecimal() accepts only plain 0-9 digits, so no signs or spaces.
    if not (month_s.isdecimal() and day_s.isdecimal() and year_s.isdecimal()):
        return False

    month = int(month_s)
    day = int(day_s)

    if month < 1 or month > 12:
        return False

    if month in (1, 3, 5, 7, 8, 10, 12):
        max_day = 31
    elif month in (4, 6, 9, 11):
        max_day = 30
    else:
        max_day = 29

    return 1 <= day <= max_day

