def select_words(s, n):
    """Return the words in s that contain exactly n consonants, in order.

    Consonants are letters other than a, e, i, o, u (case-insensitive);
    'y' counts as a consonant, matching the examples.
    """
    vowels = set("aeiouAEIOU")
    result = []
    for word in s.split():
